mapper.select:
/* Attd05Mapper.selectUserList */ WITH RECURSIVE node_tree AS ( /* 로그인 사용자의 node 부터 시작 */ SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
/* 하위 노드 무한 확장 */ SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
SELECT '' AS chk , A.CMPNY_CD AS cmpnyCd , A.USER_CD AS userCd , A.USER_ID AS userId , A.USER_NM AS userNm , A.SITE_CD AS siteCd , A.NODE_CD AS nodeCd , B.NODE_NM AS nodeNm , '' AS shiftTeam , A.MBL_NO_ENC AS mblNo FROM TB_USER A INNER JOIN node_tree B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND A.NODE_CD = B.NODE_CD ) WHERE A.ACCOUNT_STATUS != '03'
AND A.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND A.NODE_CD = #{nodeCd}

    /* Attd05Mapper.selectSchedList */
    SELECT 
		A.CMPNY_CD 			AS cmpnyCd
	    , A.SITE_CD			AS siteCd
	    , A.USER_CD 		AS userCd
	    , A.WORK_YMD		AS wrkYmd
	    , A.WORK_PLAN_CD	AS workPlanCd
	FROM TB_USER_WORK_PLAN A
	WHERE A.CMPNY_CD = #{gvCmpnyCd}
	  AND A.SITE_CD = #{siteCd}

mapper.update:
    /* Attd05Mapper.saveUserWorkPlans */
	INSERT INTO TB_USER_WORK_PLAN (
	    CMPNY_CD
	    , SITE_CD
	    , USER_CD
	    , WORK_YMD
	    , WORK_PLAN_CD
	    , INSERT_NO
	    , INSERT_DATE
	    , UPDATE_NO
	    , UPDATE_DATE
	) VALUES (
	    #{gvCmpnyCd}
	    , #{siteCd}
	    , #{userCd}
	    , #{workYmd}
	    , #{workPlanCd}
	    , #{gvUserCd}
	    , NOW()
	    , #{gvUserCd}
	    , NOW()
	) AS NEW
	ON DUPLICATE KEY UPDATE
		WORK_PLAN_CD	= NEW.WORK_PLAN_CD
	    , UPDATE_NO		= NEW.UPDATE_NO
	    , UPDATE_DATE	= NOW()

mapper.delete:
/* Attd05Mapper.deleteUserWorkPlans */
DELETE FROM TB_USER_WORK_PLAN
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND USER_CD = #{userCd}
  AND WORK_YMD LIKE CONCAT(replace(#{workYm},'-', ''), '%')
